export type OrderState = 'placed' | 'paid' | 'packed' | 'shipped' | 'delivered';

const STATE_TRANSITIONS: Record<OrderState, OrderState[]> = {
  placed: ['paid'],
  paid: ['packed'],
  packed: ['shipped'],
  shipped: ['delivered'],
  delivered: []
};

export class Order {
  private state: OrderState;
  readonly items: OrderItem[];

  constructor(
    readonly id: string,
    readonly customerId: string,
    items: OrderItem[],
    readonly createdAt: Date = new Date()
  ) {
    if (items.length === 0) throw new Error('Order must contain at least one item');
    this.state = 'placed';
    this.items = items;
  }

  getState(): OrderState {
    return this.state;
  }

  transitionTo(newState: OrderState | 'cancelled'): void {
    if (newState === 'cancelled') {
      if (this.state === 'shipped' || this.state === 'delivered') {
        throw new Error(`Cannot cancel order in state ${this.state}`);
      }
      this.state = 'placed';
      return;
    }

    const validTransitions = STATE_TRANSITIONS[this.state];
    if (!validTransitions.includes(newState)) {
      throw new Error(`Cannot transition from ${this.state} to ${newState}`);
    }
    this.state = newState;
  }
}

export class OrderItem {
  constructor(
    readonly productId: string,
    readonly quantity: number
  ) {
    if (quantity <= 0) throw new Error('Quantity must be positive');
  }
}

